-- AQARI V267 Preview/Staging: list only archived PDF versions eligible for handover.
create or replace function public.aqari_official_document_handover_context(p_workspace_id uuid,p_series_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare s private.aqari_official_document_series;begin if auth.uid() is null or not private.aqari_official_document_access(p_workspace_id,false) then raise insufficient_privilege using message='ACCESS_DENIED';end if;select * into s from private.aqari_official_document_series x where x.workspace_id=p_workspace_id and x.id=p_series_id;if not found or not private.aqari_official_entity_scope(p_workspace_id,s.entity_type,s.entity_id,'read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;return jsonb_build_object('workspace_id',p_workspace_id,'user_id',auth.uid(),'seriesId',s.id,'documentNo',s.document_no,'status',s.status,'canWrite',private.aqari_official_document_access(p_workspace_id,true) and private.aqari_official_entity_scope(p_workspace_id,s.entity_type,s.entity_id,'write'),'archivedVersions',coalesce((select jsonb_agg(jsonb_build_object('version',v.version,'title',v.title,'contentSha256',v.content_sha256,'pdfSha256',a.pdf_sha256,'archivedAt',a.archived_at) order by v.version desc) from private.aqari_official_document_versions v join private.aqari_official_pdf_artifacts a on a.workspace_id=v.workspace_id and a.series_id=v.series_id and a.version=v.version where v.workspace_id=p_workspace_id and v.series_id=s.id),'[]'::jsonb));end$$;
revoke all on function public.aqari_official_document_handover_context(uuid,uuid) from public,anon;grant execute on function public.aqari_official_document_handover_context(uuid,uuid) to authenticated;
